import {api,escape} from './workspace-shared.js';
import {courseIcon} from './course-overview.js';

export function createClassFiles({root,teacher=false,onPlan}){
  root.classList.add('class-files');let classId='',epoch=0,busy=false,state=null;
  root.innerHTML=`<div class="files-heading"><div><p class="teacher-eyebrow">YOUR COURSE LIBRARY</p><h2>Class files</h2><p>${teacher?'Keep books, unit plans and lesson resources together. Choose who can use each file.':'Download the resources your teacher has shared for this class.'}</p></div>${teacher?'<button type="button" class="teacher-button secondary" data-files-plan>Populate overview with AI</button>':''}</div>
  ${teacher?`<div class="files-upload"><h3>${courseIcon('document')} Add class files</h3><div class="setup-fields"><label>Files<input type="file" data-files-input multiple accept=".pdf,.doc,.docx,.csv,.xls,.xlsx,.txt,.vtt,.png,.jpg,.jpeg,.mp3"></label><label>File type<select data-files-kind><option value="resource">Teaching resource</option><option value="unit-plan">Unit plan / overview</option><option value="book">Book / chapter excerpt</option></select></label></div><div class="file-sharing"><label><input type="checkbox" data-files-ai> Use with AI <small>Send to OpenAI for course plans and quizzes</small></label><label><input type="checkbox" data-files-students> Allow student downloads <small>Enrolled students and linked parents</small></label></div><p>Leave both off for teacher-only storage. Documents, images and MP3 · 20 MiB each · 32 files / 200 MiB per class. AI uses documents only, up to 8 files / 40 MiB including earlier AI resources.</p><button type="button" class="teacher-button" data-files-upload>Upload files</button></div>`:''}
  <p data-files-message role="status"></p><button type="button" class="text-button" data-files-refresh>Refresh files</button><div data-files-list></div><div data-files-legacy></div>`;
  const $=s=>root.querySelector(s),message=t=>$('[data-files-message]').textContent=t;
  const size=n=>n>=1024*1024?(n/(1024*1024)).toFixed(1)+' MiB':Math.ceil(n/1024)+' KiB';
  function render(){
    $('[data-files-list]').innerHTML=state.files.length?state.files.map(f=>`<article class="class-file" data-file="${escape(f.id)}"><div class="class-file-title">${courseIcon(f.kind==='book'?'book':'document')}<div><h3>${escape(f.filename)}</h3><p>${size(f.bytes)}${teacher?' · '+escape(f.kind==='unit-plan'?'Unit plan':f.kind==='book'?'Book / excerpt':'Teaching resource'):''}</p></div><a class="teacher-button secondary" href="${escape(f.downloadURL)}" download>Download<span class="visually-hidden"> ${escape(f.filename)}</span></a></div>${teacher?`<div class="file-sharing"><label><input type="checkbox" data-file-ai ${f.aiEnabled?'checked':''} ${f.aiSupported?'':'disabled'}> Use with AI <small>${f.aiSupported?'Available for planning and quiz generation':'Upload a PDF or transcript for AI'}</small></label><label><input type="checkbox" data-file-students ${f.studentDownload?'checked':''}> Allow student downloads <small>${f.studentDownload?'Visible to this class and linked parents':'Hidden from students and parents'}</small></label></div><div class="teacher-actions"><button type="button" class="text-button" data-file-save="${escape(f.id)}" ${f.busy?'disabled':''}>Save sharing<span class="visually-hidden"> for ${escape(f.filename)}</span></button><button type="button" class="text-button danger-text" data-file-remove="${escape(f.id)}" ${f.busy?'disabled':''}>Remove<span class="visually-hidden"> ${escape(f.filename)}</span></button>${f.busy?'<span>Updating… Refresh shortly.</span>':''}</div>`:''}</article>`).join(''):`<div class="files-empty">${courseIcon('document')}<h3>${teacher?'Your class library starts here':'No downloads yet'}</h3><p>${teacher?'Upload a unit plan to use with AI, or share a reading or worksheet with students.':'Files will appear here when your teacher shares them.'}</p></div>`;
    $('[data-files-legacy]').innerHTML=teacher&&state.legacy.length?`<details class="planner-source"><summary>Earlier AI resources (${state.legacy.length})</summary><p>These files are already available to AI. Upload a copy above to also make them downloadable. Removing a source does not remove previously generated plans or quizzes.</p>${state.legacy.map(f=>`<p class="legacy-file"><span>${escape(f.filename)} · ${size(f.bytes)}</span><button type="button" class="text-button danger-text" data-legacy-remove="${escape(f.id)}">Remove<span class="visually-hidden"> ${escape(f.filename)}</span></button></p>`).join('')}</details>`:'';
  }
  async function refresh(){const version=epoch,id=classId;const result=await api(`/api/class-files/classes/${id}`);if(version!==epoch)return;state=result;render();}
  async function run(work){if(busy)return;busy=true;const version=epoch;root.querySelectorAll('button,input,select').forEach(e=>e.disabled=true);try{await work(version);}catch(e){if(version===epoch)message(e.message);}finally{if(version===epoch){busy=false;root.querySelectorAll('button,input,select').forEach(e=>e.disabled=false);if(state)render();}}}
  $('[data-files-refresh]').onclick=()=>run(async()=>{await refresh();message('Files refreshed.');});
  if(teacher){
    $('[data-files-plan]').onclick=()=>{if(!busy)onPlan?.(classId);};
    $('[data-files-upload]').onclick=()=>run(async version=>{
      const files=[...$('[data-files-input]').files],id=classId,ai=$('[data-files-ai]').checked,students=$('[data-files-students]').checked,kind=$('[data-files-kind]').value;
      if(!files.length)throw Error('Choose at least one file.');if(files.length>32||files.some(f=>!f.size||f.size>20*1024*1024))throw Error('Choose up to 32 files, each 20 MiB or smaller.');
      let uploaded=0;
      try{for(const file of files){message(`Uploading ${file.name} (${uploaded+1} of ${files.length})…`);const body=new FormData();body.append('file',file);body.append('kind',kind);body.append('aiEnabled',String(ai));body.append('studentDownload',String(students));state=await api(`/api/class-files/classes/${id}`,body,{timeoutMs:115000});if(version!==epoch)return;uploaded++;render();}}finally{$('[data-files-input]').value='';}
      message(`${uploaded} ${uploaded===1?'file':'files'} uploaded. ${students?'Student downloads are enabled.':'Files are hidden from students and parents.'}`);
      document.dispatchEvent(new CustomEvent('inkwire:class-files-changed',{detail:{classId:id}}));
    });
    root.addEventListener('click',event=>{
      const save=event.target.closest('[data-file-save]'),remove=event.target.closest('[data-file-remove]'),legacy=event.target.closest('[data-legacy-remove]');if(!save&&!remove&&!legacy||busy)return;
      if((remove||legacy)&&!confirm('Remove this file from the class and AI? Existing plans and quiz drafts will remain.'))return;
      const id=save?.dataset.fileSave||remove?.dataset.fileRemove,row=state.files.find(f=>f.id===id),card=save?.closest('[data-file]');
      const body=legacy?{action:'remove',id:legacy.dataset.legacyRemove}:{action:save?'sharing':'remove',id,revision:row.revision,...(save?{aiEnabled:card.querySelector('[data-file-ai]').checked,studentDownload:card.querySelector('[data-file-students]').checked}:{})};
      run(async()=>{message(save?'Saving sharing settings…':'Removing file…');await api(legacy?`/api/course-resources/classes/${classId}`:`/api/class-files/classes/${classId}`,body,{timeoutMs:115000});await refresh();message(save?'Sharing settings saved. Turning off AI stops future use of this source; existing drafts remain.':'File removed.');document.dispatchEvent(new CustomEvent('inkwire:class-files-changed',{detail:{classId}}));});
    });
  }
  return {isBusy:()=>busy,clear(){epoch++;classId='';state=null;busy=false;$('[data-files-list]').replaceChildren();},async open(id){if(busy)return;classId=id;epoch++;state=null;$('[data-files-list]').replaceChildren();$('[data-files-legacy]').replaceChildren();if(teacher){$('[data-files-input]').value='';$('[data-files-ai]').checked=false;$('[data-files-students]').checked=false;}message('Loading class files…');try{await refresh();message('');}catch(e){message(e.message);}}};
}
